('pj_sci01','project','science','project','نزرع حبة فول','x_seed',array['a5','a6','g1','g2']::text[],'العلوم','ملاحظة نمو النبات','easy','نزرع حبة فول في كوب وننتظر لنرى الجذر ثم الساق.','أن أرى كيف تنبت البذرة وتنمو.',15,$j${"goal": "أن أرى كيف تنبت البذرة وتنمو.", "tools": ["كوب شفاف", "قطن", "حبة فول", "ماء", "ملعقة"], "steps": [{"t": "نبلل القطن بقليل من الماء ونضعه في الكوب.", "i": "x_jar", "p": "ساعد الطفل على سكب الماء ببطء."}, {"t": "نضع حبة الفول بين القطن وجدار الكوب حتى نراها.", "i": "x_seed"}, {"t": "نضع الكوب قرب النافذة في مكان مضيء.", "i": "2600"}, {"t": "نرش القليل من الماء كل يوم بالملعقة ليبقى القطن رطبا.", "i": "x_spoon"}, {"t": "ننظر كل يوم ونرسم ما نراه: جذر ثم ساق ثم ورقة.", "i": "1f50d"}], "safety": "اغسل يديك بعد اللمس ولا تضع البذرة في فمك.", "outcome": "يعرف الطفل أن البذرة تحتاج إلى ماء وضوء لتنمو، وأن الجذر يظهر أولا.", "adult": true, "skills": ["ملاحظة التغير", "الصبر والمتابعة", "أجزاء النبات"], "qs": [{"q": "ماذا يظهر من البذرة أولا؟", "o": ["الجذر", "الزهرة", "الثمرة"], "why": "يظهر الجذر أولا ليمتص الماء."}, {"q": "ماذا تحتاج النبتة لتنمو؟", "o": ["ماء وضوء", "ظلام فقط", "حجارة فقط"], "why": "تحتاج النبتة إلى الماء والضوء."}]}$j$::jsonb,$j${"href": "experiments/", "label": "التجارب والمشاريع العلمية"}$j$::jsonb,'مشروع أصلي من إنتاج زاد: خطواته وأدواته آمنة ومن مواد البيت، وفُحصت لغته وبنيته آليا، ولم يراجعه مختص تربوي بعد.',true,'published',1),
('pj_sci02','project','science','project','سجل نمو النبتة','x_plant',array['g2','g3','g4']::text[],'العلوم','تسجيل الملاحظات وقياس الطول','mid','نقيس طول نبتة كل يومين ونسجل الأرقام في جدول.','أن أسجل نمو النبتة بالأرقام والرسم.',20,$j${"goal": "أن أسجل نمو النبتة بالأرقام والرسم.", "tools": ["نبتة صغيرة", "مسطرة", "ورقة وقلم", "قلم رصاص ملون"], "steps": [{"t": "نرسم جدولا من عمودين: اليوم والطول.", "i": "i_notebook"}, {"t": "نقيس طول النبتة بالمسطرة من التربة إلى أعلى ورقة.", "i": "1f4cf", "p": "اقرأ الرقم مع الطفل وتأكد من وقوف المسطرة مستقيمة."}, {"t": "نكتب الطول في الجدول ونرسم النبتة بجانبه.", "i": "270f"}, {"t": "نكرر القياس بعد يومين وبعد أربعة أيام.", "i": "1f4c5"}, {"t": "نقارن الأرقام: هل زاد الطول؟ بكم زاد؟", "i": "i_chart"}], "safety": "اسق النبتة بكمية قليلة وانتبه حتى لا يسقط الإناء.", "outcome": "يتعلم الطفل القياس وتسجيل الأرقام ومقارنتها لمعرفة مقدار النمو.", "adult": false, "skills": ["القياس بالمسطرة", "تسجيل البيانات", "المقارنة بين الأرقام"], "qs": [{"q": "ماذا نستعمل لقياس طول النبتة؟", "o": ["المسطرة", "الملعقة", "الكوب"], "why": "نقيس الطول بالمسطرة."}, {"q": "كيف نعرف أن النبتة نمت؟", "o": ["يزيد طولها في الجدول", "يقل لونها", "تنقص أوراقها"], "why": "إذا زاد الرقم في الجدول فالنبتة نمت."}]}$j$::jsonb,$j${"href": "experiments/", "label": "التجارب والمشاريع العلمية"}$j$::jsonb,'مشروع أصلي من إنتاج زاد: خطواته وأدواته آمنة ومن مواد البيت، وفُحصت لغته وبنيته آليا، ولم يراجعه مختص تربوي بعد.',true,'published',2),
('pj_sci03','project','science','project','هل يطفو أم يغرق؟','x_water',array['a5','a6','g1','g2']::text[],'العلوم','التوقع والملاحظة','easy','نجرب أشياء مختلفة في وعاء ماء ونرى ما يطفو وما يغرق.','أن أتوقع ثم أجرب وألاحظ.',15,$j${"goal": "أن أتوقع ثم أجرب وألاحظ.", "tools": ["وعاء كبير فيه ماء", "ملعقة", "قلم", "ورقة", "حجر صغير", "ثمرة تفاح"], "steps": [{"t": "نضع الأشياء أمامنا ونتوقع: أيها سيطفو وأيها سيغرق؟", "i": "1f914"}, {"t": "نضع الشيء الأول برفق في الماء وننظر ماذا حدث.", "i": "x_bucket", "p": "اجعل الطفل يضع كل شيء بنفسه ببطء."}, {"t": "نكرر مع بقية الأشياء ونضعها في مجموعتين: يطفو ويغرق.", "i": "x_stone"}, {"t": "نقارن توقعاتنا بالنتائج ونتحدث عما فاجأنا.", "i": "1f4a1"}], "safety": "نجرب على طاولة وننشف الماء المسكوب فورا حتى لا ننزلق.", "outcome": "يعرف الطفل أن بعض الأشياء تطفو وبعضها يغرق، وأن التجربة تبين الحقيقة.", "adult": true, "skills": ["التوقع", "التصنيف", "الملاحظة"], "qs": [{"q": "ماذا حدث للحجر في الماء؟", "o": ["غرق", "طفا", "اختفى"], "why": "الحجر الصغير يغرق في الماء."}, {"q": "لماذا نجرب بأنفسنا؟", "o": ["لنتأكد من توقعنا", "لنلعب فقط", "لنسكب الماء"], "why": "التجربة تؤكد توقعنا أو تصححه."}]}$j$::jsonb,$j${"href": "experiments/", "label": "التجارب والمشاريع العلمية"}$j$::jsonb,'مشروع أصلي من إنتاج زاد: خطواته وأدواته آمنة ومن مواد البيت، وفُحصت لغته وبنيته آليا، ولم يراجعه مختص تربوي بعد.',true,'published',3),
