('pj_eng02','project','english','project','My picture dictionary','i_book',array['a6','g1','g2','g3','g4']::text[],'اللغة الإنجليزية','Learning new words with pictures','mid','We make a small book with a word and a picture on every page.','To collect new English words and use them.',30,$j${"goal": "To collect new English words and use them.", "tools": ["Two folded papers", "A pencil", "Colored pencils"], "steps": [{"t": "Fold the papers and write My dictionary on the cover.", "i": "i_notebook", "p": "Help with the cover and the page order."}, {"t": "Choose a word like dog and write it at the top of a page.", "i": "1f436"}, {"t": "Draw the picture and write a short sentence: This is a dog.", "i": "270f"}, {"t": "Add a new word on every page and read the book aloud.", "i": "1f4d6"}], "safety": "Use paper and pencils only.", "outcome": "The child learns words, links them with pictures and writes a simple sentence.", "adult": false, "skills": ["New vocabulary", "Writing simple sentences", "Reading aloud"], "qs": [{"q": "What do we write under the picture?", "o": ["A short sentence", "A phone number", "Nothing"], "why": "A sentence shows how the word is used."}, {"q": "Why do we draw a picture?", "o": ["To remember the meaning", "To hide the word", "To waste paper"], "why": "Pictures help us remember."}]}$j$::jsonb,$j${"href": "language/", "label": "اللغة والبطاقات"}$j$::jsonb,'مشروع أصلي من إنتاج زاد: خطواته وأدواته آمنة ومن مواد البيت، وفُحصت لغته وبنيته آليا، ولم يراجعه مختص تربوي بعد.',true,'published',302),
